import{_ as a,C as s,o as r,c as d,E as o,a3 as i}from"./chunks/framework.DFqf6Kfg.js";const n="/versions/v0.19.89/screens/devices/cc-value-filter.png",l="/versions/v0.19.89/screens/devices/cc-value-filter-wrap.png",b=JSON.parse('{"title":"CC Value Filter","description":"","frontmatter":{"title":"CC Value Filter","pageClass":"device-doc"},"headers":[],"relativePath":"devices/cc-value-filter.md","filePath":"devices/cc-value-filter.md"}'),h={name:"devices/cc-value-filter.md"};function c(p,e,u,g,v,m){const t=s("DeviceHeading");return r(),d("div",null,[o(t,{slug:"cc-value-filter",title:"CC Value Filter"}),e[0]||(e[0]=i('<p>Filter CC by value</p><p><img src="'+n+'" alt="CC Value Filter parameters" class="screen"></p><p>The right side draws the CC values 0–127 as a track. A CC whose value is on the solid part passes; a CC on the dotted part is dropped. Bright markers sit at <strong>RNG START</strong> and <strong>RNG END</strong>. Messages that are not CCs always pass.</p><p>A small pointer under the track shows the last CC value received. The <strong>LAST</strong> line names it: bright when it passed, dim when it was blocked.</p><p>When <strong>RNG START</strong> is above <strong>RNG END</strong>, the range wraps around: 100 to 20 keeps 100–127 and 0–20.</p><p><img src="'+l+'" alt="CC Value Filter, wrap-around" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Use <strong>CC Value Filter</strong> to <strong>pass or block CC messages by value range</strong> — e.g. only allow sustain pedal values above half. Notes, clock, and other non-CC messages pass through unchanged.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>RNG START</td><td>0 – 127</td><td>Low CC value of the window.</td></tr><tr><td>RNG END</td><td>0 – 127</td><td>High CC value of the window.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table>',13))])}const _=a(h,[["render",c]]);export{b as __pageData,_ as default};
